-- ---------------------------------------------------------------------------
-- 2. The Manuals asset category and the documents on it.
--    EcomDetailsGroupId is an INT IDENTITY, so the group is addressed by its
--    SYSTEM NAME everywhere and its id is looked up, never asserted.
-- ---------------------------------------------------------------------------
IF NOT EXISTS (SELECT 1 FROM EcomDetailsGroup WHERE EcomDetailsGroupSystemName = 'Manuals')
    INSERT INTO EcomDetailsGroup (EcomDetailsGroupSystemName, DetailsGroupInheritanceType, DetailsGroupExtensions, DetailsGroupControlType, DetailsGroupIsSystemGroup, DetailsGroupSortingMode, DetailsGroupIsPrimaryImageRule, DetailsGroupHasPrimaryImageRule, DetailsGroupInheritDefaultImageAcrossVariants, DetailsGroupInheritDefaultImageAcrossLanguages)
    VALUES ('Manuals', 3, 'pdf', 0, 0, 0, 0, 0, 1, 1);

-- A NULL ControlType or InheritanceType on this group renders zero links on
-- every PDP, silently. Converge a host that already carries a half-made group
-- rather than leaving the failure in place.
IF EXISTS (SELECT 1 FROM EcomDetailsGroup WHERE EcomDetailsGroupSystemName = 'Manuals' AND (DetailsGroupControlType IS NULL OR DetailsGroupInheritanceType IS NULL OR ISNULL(DetailsGroupExtensions, N'') = N''))
    UPDATE EcomDetailsGroup SET DetailsGroupControlType = 0, DetailsGroupInheritanceType = 3, DetailsGroupExtensions = 'pdf' WHERE EcomDetailsGroupSystemName = 'Manuals';

DECLARE @TcManualsGroupId INT = (SELECT TOP 1 EcomDetailsGroupId FROM EcomDetailsGroup WHERE EcomDetailsGroupSystemName = 'Manuals');
IF @TcManualsGroupId IS NULL
    RAISERROR(N'truvio-pdp.sql: the Manuals asset category was not created. The PDP documents table has nothing to bind to.', 16, 1);
