-- ---------------------------------------------------------------------------
-- RESOLUTION GUARDS. Each asserts what the PAGE needs, not what was inserted.
-- ---------------------------------------------------------------------------
DECLARE @TcThinGalleries INT = (
    SELECT COUNT(*) FROM (
        SELECT d.DetailProductId FROM EcomDetails d
         WHERE d.DetailProductId LIKE 'TCPROD%' AND d.DetailVariantId = ''
         GROUP BY d.DetailProductId HAVING COUNT(*) < 2) x);
IF @TcThinGalleries > 0
    RAISERROR(N'truvio-pdp.sql: a master carries fewer than two gallery images. The thumbnail strip does not render for a single image, so the PDP would open on one picture with nothing to step through.', 16, 1);

DECLARE @TcDocLess INT = (
    SELECT COUNT(*) FROM EcomProducts p
     WHERE p.ProductId LIKE 'TCPROD%' AND p.ProductVariantId = '' AND p.ProductLanguageId = 'ENU'
       AND (SELECT COUNT(*) FROM EcomDetails d WHERE d.DetailProductId = p.ProductId AND d.DetailsGroupId = @TcManualsGroupId) < 2);
IF @TcDocLess > 0
    RAISERROR(N'truvio-pdp.sql: a master carries fewer than two Manuals rows. The documents table would render a heading over an empty or one-line table.', 16, 1);

DECLARE @TcRelationLess INT = (
    SELECT COUNT(*) FROM EcomProducts p
     WHERE p.ProductId LIKE 'TCPROD%' AND p.ProductVariantId = '' AND p.ProductLanguageId = 'ENU'
       AND (SELECT COUNT(*) FROM EcomProductsRelated r WHERE r.ProductRelatedProductId = p.ProductId) < 2);
IF @TcRelationLess > 0
    RAISERROR(N'truvio-pdp.sql: a master shows fewer than two related products. The relations strip would render a stranded section head, which is what marine ships on its own flagship page and what this layer exists not to repeat.', 16, 1);

DECLARE @TcThinSpecs INT = (
    SELECT COUNT(*) FROM EcomProducts p
     WHERE p.ProductId LIKE 'TCPROD%' AND p.ProductVariantId = '' AND p.ProductLanguageId = 'ENU'
       AND (SELECT COUNT(*) FROM EcomProductCategoryFieldValue v
             WHERE v.FieldValueProductId = p.ProductId AND v.FieldValueProductVariantId = ''
               AND ISNULL(v.FieldValueValue, N'') <> N'') <> 7);
IF @TcThinSpecs > 0
    RAISERROR(N'truvio-pdp.sql: a master does not carry exactly seven specification values. The table is meant to read seven of seven on every page; a partial row set is the thin table the parity report measured.', 16, 1);

COMMIT TRAN;
PRINT 'Done - truvio-demo PDP fill: 84 gallery rows (2 to 3 images per master), the Manuals asset category and 120 document rows over 8 layer-shipped PDFs, 324 relations in 3 groups, 240 category-field values taking every specification table to seven of seven.';
